def pre(x):
    return And(x >= 0, x <= 9999)

def post(x, r):
    # Decimal digits of x, least significant first (x has at most 4 digits).
    d0 = x % 10
    d1 = (x // 10) % 10
    d2 = (x // 100) % 10
    d3 = (x // 1000) % 10
    # Reversed number, with leading zeros dropped (value is unchanged).
    rev = d0 * 1000 + d1 * 100 + d2 * 10 + d3
    return Or(And(rev > x, r == 1), And(Not(rev > x), r == 0))
